    const btn = e.target?.closest?.('#final-mobile-chrome [data-chrome-action]');
    if (!btn) return false;

    // Music toggle: only handle on 'click' to prevent double-toggle via pointerup/touchend
    const action = btn.getAttribute('data-chrome-action');
    if (action === 'music' && e.type !== 'click') return false;

    const now = Date.now();
    if (now - lastChromeActionAt < 260) {
      e.preventDefault();
      e.stopPropagation();
      if (e.stopImmediatePropagation) e.stopImmediatePropagation();
      return true;
    }

    lastChromeActionAt = now;
    keepChromeActionsOnTop();
    e.preventDefault();
    e.stopPropagation();
    if (e.stopImmediatePropagation) e.stopImmediatePropagation();
    handleChromeAction(btn.getAttribute('data-chrome-action'), btn);
    return true;
