        var customIcon =
          (document.body &&
            document.body.getAttribute("data-fall-custom-icon")) ||
          params.get("fall_icon") ||
          "";
        var customIconsAttr =
          (document.body &&
            document.body.getAttribute("data-fall-custom-icons")) ||
          params.get("fall_icons") ||
          "";
